const SB='https://addwjngdezmmnxddulll.supabase.co/rest/v1';
const KEY='<REDACTED_SUPABASE_JWT>';
const H={apikey:KEY,Authorization:'Bearer '+KEY};
const comps=await this.helpers.httpRequest({method:'GET',url:SB+'/competitors?select=name,linkedin_urn&active=eq.true',headers:H,json:true});
const urn=new Set((comps||[]).map(c=>String(c.linkedin_urn||'')).filter(Boolean));
const aff=await this.helpers.httpRequest({method:'GET',url:SB+'/author_affiliation?select=key,verdict',headers:H,json:true});
const verdictByKey={};for(const a of (aff||[])){if(a&&a.key)verdictByKey[String(a.key)]=a.verdict;}
// Stream attributed LI posts in small pages; fold DISTINCT candidate authors into byKey; discard each page.
// (Loading all posts + full text at once OOMs the tight n8n worker — 2026-07-08.)
const byKey={}; let off=0; const PAGE=200;
for(;;){
  const b=await this.helpers.httpRequest({method:'GET',url:SB+'/linkedin_posts?select=companyName,author,text,posted_at&companyName=neq.NONE&companyName=not.is.null&order=posted_at.desc&limit='+PAGE+'&offset='+off,headers:H,json:true});
  const page=Array.isArray(b)?b:[];
  for(const r of page){
    const a=(r.author&&typeof r.author==='object')?r.author:null; if(!a)continue;
    const pid=String(a.profile_id||''); if(!pid)continue;
    if(urn.has(pid))continue;
    if(verdictByKey[pid]==='employee')continue;
    if(!byKey[pid]){byKey[pid]={key:pid,profile_id:pid,competitor:r.companyName,name:a.name||'',headline:a.headline||'',texts:[],ts:r.posted_at};}
    const e=byKey[pid];
    if(e.texts.length<2 && r.text){e.texts.push(String(r.text).replace(/\s+/g,' ').slice(0,400));}
  }
  if(page.length<PAGE)break;
  off+=PAGE;
}
let cands=Object.values(byKey);
cands.sort((x,y)=>String(y.ts).localeCompare(String(x.ts)));
cands=cands.slice(0,60);
if(!cands.length)return [];
const promptList=cands.map((c,i)=>({idx:i,competitor:c.competitor,name:c.name,headline:c.headline,posts:c.texts}));
const openaiBody={model:'gpt-4.1',temperature:0,response_format:{type:'json_object'},messages:[{role:'system',content:"You classify the RELATIONSHIP between a LinkedIn author and a competitor company, for a competitive-intelligence tool at Twine Security. You are given a list of authors; each has: idx, competitor (the company their post was attributed to), the author's name, their LinkedIn headline, and 1-2 of their post texts (about that competitor). For EACH author, decide their relationship to THAT competitor and return exactly one label:\n- \"employee\": the author currently works at the competitor, OR is announcing they JUST JOINED / are JOINING / STARTING a role there (e.g. 'excited to join <competitor>', 'Day 1 at <competitor>', 'starting a new position at <competitor>', or a headline like 'VP at <competitor>'). Incoming/just-joined counts as employee.\n- \"external\": anyone else — a customer, partner, investor, event organizer, a person who works at a DIFFERENT company (even if they mention or praise the competitor), a commentator/analyst, OR an EX-employee who is LEAVING or has LEFT (departure/farewell posts, 'ex-<competitor>', 'my last day at <competitor>', now at another company).\nKey distinctions: JOINING = employee; LEAVING/DEPARTED = external; working at another company while mentioning the competitor = external. When the headline names a DIFFERENT current employer, choose external unless the post clearly announces joining the competitor. Return ONLY a JSON object: {\"results\":[{\"idx\":<int>,\"relation\":\"employee\"|\"external\"}]} with one entry per input author, no prose."},{role:'user',content:'Authors to classify (JSON):\n'+JSON.stringify(promptList)}]};
return [{json:{candidates:cands,openaiBody}}];

const SB='https://addwjngdezmmnxddulll.supabase.co/rest/v1';
const KEY='<REDACTED_SUPABASE_JWT>';
const H={apikey:KEY,Authorization:'Bearer '+KEY,'Content-Type':'application/json',Prefer:'resolution=merge-duplicates,return=minimal'};
const llm=$input.first().json;
let content='';
if(llm&&llm.choices&&llm.choices[0]&&llm.choices[0].message)content=llm.choices[0].message.content||'';
else if(llm&&llm.message&&llm.message.content)content=llm.message.content;
else if(typeof llm==='string')content=llm;
let parsed={results:[]};try{parsed=JSON.parse(content);}catch(e){parsed={results:[]};}
const results=Array.isArray(parsed.results)?parsed.results:[];
const src=$('Fetch Candidates').first().json;
const cands=(src&&src.candidates)||[];
const now=new Date().toISOString();
const rows=[];
for(const res of results){
  const c=cands[Number(res.idx)];
  if(!c)continue;
  const v=(res.relation==='employee')?'employee':'external';
  rows.push({key:c.key,profile_id:c.profile_id,name:c.name,competitor:c.competitor,verdict:v,employer:(v==='employee'?c.competitor:null),method:'llm',checked_at:now});
}
if(!rows.length)return [{json:{classified:0,candidates:cands.length}}];
let ok=false,err='';
try{await this.helpers.httpRequest({method:'POST',url:SB+'/author_affiliation?on_conflict=key',headers:H,body:rows,json:true});ok=true;}
catch(e){err=String((e&&e.message)||e).slice(0,300);}
const emp=rows.filter(r=>r.verdict==='employee').length;
return [{json:{classified:ok?rows.length:0,employees:emp,externals:rows.length-emp,candidates:cands.length,ok,error:err}}];
